(5929522, 863029, 38433, '<td valign="top">This could have been much better if you used a more vibrant colored orange to really depict the theme. Here, it looks like it is lime instead of an orange.<br/> <br/>Yet, this photo is really nice. I love how the bubbles animate the shot.</td>', 'This could have been much better if you used a more vibrant colored orange to really depict the theme. Here, it looks like it is lime instead of an orange. Yet, this photo is really nice. I love how the bubbles animate the shot.', '2010-04-03 23:33:23.000000', NULL, 1),
(5929579, 862947, 94239, '<td valign="top">Like a painting, lovely.</td>', 'Like a painting, lovely.', '2010-04-04 00:36:09.000000', NULL, 1),
(5929581, 862384, 94239, '<td valign="top">Cute and funny, well done.</td>', 'Cute and funny, well done.', '2010-04-04 00:36:57.000000', NULL, 1),
(5929666, 863551, 15511, '<td valign="top">Remarkably, the softness of your image evokes a warm, comfortable feel, as opposed to being very sharp, which would better convey the danger inherent in the wild beast.</td>', 'Remarkably, the softness of your image evokes a warm, comfortable feel, as opposed to being very sharp, which would better convey the danger inherent in the wild beast.', '2010-04-04 03:18:27.000000', NULL, 1),
(5929784, 863569, 28427, '<td valign="top">The background is distracting.  Next time try to keep more distance between your subject and the background. I also think that black would have been better than this blue. But thank you for making me discover this flower (until know I only knew the Calla and the Cana, but never heard of the Cama)</td>', 'The background is distracting.  Next time try to keep more distance between your subject and the background. I also think that black would have been better than this blue. But thank you for making me discover this flower (until know I only knew the Calla and the Cana, but never heard of the Cama)', '2010-04-04 09:19:52.000000', NULL, 1),
(5930054, 863614, 100335, '<td valign="top">stunning colors, in love with this image, 10 and a fave from me. hope you blue.</td>', 'stunning colors, in love with this image, 10 and a fave from me. hope you blue.', '2010-04-04 13:32:18.000000', NULL, 1),
(5930058, 863355, 100335, '<td valign="top">ok i appreciate the creativity and lighting here but....... those eyelashes are just freaky lol</td>', 'ok i appreciate the creativity and lighting here but....... those eyelashes are just freaky lol', '2010-04-04 13:34:21.000000', NULL, 1),
(5930063, 862947, 100335, '<td valign="top">Great perspective, i love that i can see some sky in there, it really adds to the mood. 8</td>', 'Great perspective, i love that i can see some sky in there, it really adds to the mood. 8', '2010-04-04 13:36:23.000000', NULL, 1),
(5930064, 862314, 100335, '<td valign="top">Hahah just want to slap it..... in a loving way</td>', 'Hahah just want to slap it..... in a loving way', '2010-04-04 13:36:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5930072, 863696, 100335, '<td valign="top">Great lighting, unfortunately its on a very common theme in this challenge. Still gets high scores. Is this painted with light?</td>', 'Great lighting, unfortunately its on a very common theme in this challenge. Still gets high scores. Is this painted with light?', '2010-04-04 13:38:04.000000', NULL, 1),
(5930287, 863689, 47974, '<td valign="top">Don''t really see any orange.</td>', 'Don''t really see any orange.', '2010-04-04 18:23:46.000000', NULL, 1),
(5930291, 862506, 47974, '<td valign="top">Looks red on my computer.</td>', 'Looks red on my computer.', '2010-04-04 18:25:12.000000', NULL, 1),
(5930293, 863508, 47974, '<td valign="top">The whites are really blown but I love the reflection in the surface.</td>', 'The whites are really blown but I love the reflection in the surface.', '2010-04-04 18:26:25.000000', NULL, 1),
(5930295, 862466, 47974, '<td valign="top">Like the object photographed but the background is to busy</td>', 'Like the object photographed but the background is to busy', '2010-04-04 18:28:10.000000', NULL, 1),
(5930300, 863688, 47974, '<td valign="top">Focus is a little soft.  Love the concept</td>', 'Focus is a little soft.  Love the concept', '2010-04-04 18:31:11.000000', NULL, 1),
(5930405, 863378, 96679, '<td valign="top">Very nice set up.  Maybe just me, but I would prefer to have the center bean in focus to give my eye one point to rest upon.</td>', 'Very nice set up.  Maybe just me, but I would prefer to have the center bean in focus to give my eye one point to rest upon.', '2010-04-04 20:18:35.000000', NULL, 1),
(5930413, 863632, 114080, '<td valign="top">note: 8/10</td>', 'note: 8/10', '2010-04-04 20:25:39.000000', NULL, 1),
(5930417, 863407, 114080, '<td valign="top">Note 9/10. One point lost because of the beer in the bride''s hand. Champagne would have been perfect!</td>', 'Note 9/10. One point lost because of the beer in the bride''s hand. Champagne would have been perfect!', '2010-04-04 20:27:35.000000', NULL, 1),
(5930419, 863264, 114080, '<td valign="top">Note 7,5/10</td>', 'Note 7,5/10', '2010-04-04 20:28:47.000000', NULL, 1),
(5930513, 863687, 114969, '<td valign="top">Wonderful shot, I just love it, everything is excellent.</td>', 'Wonderful shot, I just love it, everything is excellent.', '2010-04-04 21:25:17.000000', NULL, 1),
(5930514, 863204, 114969, '<td valign="top">Excellent lighting and focus, beautifully executed.</td>', 'Excellent lighting and focus, beautifully executed.', '2010-04-04 21:26:36.000000', NULL, 1),
(5930516, 863683, 114969, '<td valign="top">Beautiful. I love the subtle blue light.</td>', 'Beautiful. I love the subtle blue light.', '2010-04-04 21:28:39.000000', NULL, 1),
(5930518, 863223, 114969, '<td valign="top">Incredible shot! The colours are just fantastic, I can feel the warmth from there :-)</td>', 'Incredible shot! The colours are just fantastic, I can feel the warmth from there :-)', '2010-04-04 21:30:49.000000', NULL, 1),
(5930528, 863590, 70503, '<td valign="top">Oh this is gorgeous! I love the brightness of the oranges and the foreground is amazing. Nice composition. Well done!</td>', 'Oh this is gorgeous! I love the brightness of the oranges and the foreground is amazing. Nice composition. Well done!', '2010-04-04 21:47:48.000000', NULL, 1),
(5930529, 863283, 70503, '<td valign="top">Lovely DoF and shot of the squirrel. Nice job.</td>', 'Lovely DoF and shot of the squirrel. Nice job.', '2010-04-04 21:48:32.000000', NULL, 1),
(5930530, 863639, 70503, '<td valign="top">LOL...this is great!</td>', 'LOL...this is great!', '2010-04-04 21:48:53.000000', NULL, 1),
(5930531, 863264, 70503, '<td valign="top">Nice DoF and composition. Meets challenge. Well done.</td>', 'Nice DoF and composition. Meets challenge. Well done.', '2010-04-04 21:49:18.000000', NULL, 1),
(5930533, 863561, 70503, '<td valign="top">Pretty. I like it a lot.</td>', 'Pretty. I like it a lot.', '2010-04-04 21:49:39.000000', NULL, 1),
(5930536, 863687, 70503, '<td valign="top">Gorgeous shot!!</td>', 'Gorgeous shot!!', '2010-04-04 21:50:15.000000', NULL, 1),
(5930561, 863196, 7560, '<td valign="top">My favorite of the challenge. Love the long exposure, the colors, and the pillar of light. 10</td>', 'My favorite of the challenge. Love the long exposure, the colors, and the pillar of light. 10', '2010-04-04 22:18:17.000000', NULL, 1),
(5930605, 862899, 109341, '<td valign="top">I would rate this higher if it wasn''t so obviously posed.  It has a look of street photography but loses interest as the expression on subject''s face and props do not seem natural.</td>', 'I would rate this higher if it wasn''t so obviously posed.  It has a look of street photography but loses interest as the expression on subject''s face and props do not seem natural.', '2010-04-04 23:02:15.000000', NULL, 1),
